-- 9017_s4_gateway_catalog_binding.sql -- S4 CORE-7 Gateway support (UA V1.2 §8, §9.1; AIH V1.2 §2 DD-21; AE V1.2 §6;
-- Amendment 03 §5.2 B1-B9; disposition OBJ-258...OBJ-271). Expand-only. Not in the V1.2 migration register (which lists
-- exactly 9002-9016): added under DELEGATED_DECISION D-CORE7-1 because the Gateway's binding checks cannot fail closed
-- without a database function that returns the binding facts to the Worker, and the catalog is specified as
-- COMMENT ON FUNCTION metadata of the Core.
--   NEW: bnx.wrk_binding_facts (B1 identity, B2 deployable config digests, B3 schema heads per lane, B8 ACTIVE flags, catalog
--        digest; bnx_worker only), bnx.wrk_catalog (the bnx-tools/1.0 entries read from the function comments, their
--        digest and every REST-callable function that has none), bnx.wrk_defer_item (a work item of a kind the running
--        Worker does not know stays queued with back-off and an Owner alert after 3 attempts; never done, never dead:
--        UA §9.1 S4B-F13, AT-Q-02), bnx.q_evidence_upload_target (what the Gateway needs to presign an R2 PUT for an
--        evidence file the caller registered and has not uploaded yet: UA §8.1, AT-EV-01; the upload itself is gated by O-7).
--   MODIFY: bnx.resolve_actor (9011 body; changed only where marked "9017"): B7 — a bearer token bound to a resource
--        (9009 audience) is refused when the Gateway presents another audience.
--   COMMENT ON FUNCTION for every bnx.cmd_*/q_* function bnx_app may execute: the bnx-tools/1.0 catalog, generated by
--        tools/s4/catalog_build.py (block between the @@CATALOG markers; never edited by hand).
set role bnx_definer;

-- ---------- B7 in resolve_actor (MODIFY, 9011 body) ----------
create or replace function bnx.resolve_actor(cred jsonb) returns bnx.actor
language plpgsql set search_path = pg_catalog, pg_temp as $$
declare h bytea; r record; a bnx.actor; k text; val text;
begin
  if cred is null or cred->>'secret' is null or length(cred->>'secret') < 32 then
    perform bnx.fail('UNAUTHENTICATED', 'P0401');
  end if;
  h := bnx.h(cred->>'secret');
  if cred->>'kind' = 'session' then
    select s.id, s.member_id, s.revoked_at, s.absolute_expires_at, s.last_seen_at, m.state into r
      from bnx.member_session s join bnx.member m on m.id = s.member_id where s.token_sha256 = h;
    if not found or r.revoked_at is not null or now() > r.absolute_expires_at
       or now() > r.last_seen_at + interval '30 days' or r.state <> 'active' then
      perform bnx.fail('UNAUTHENTICATED', 'P0401');
    end if;
    if r.last_seen_at < now() - interval '1 hour' then update bnx.member_session set last_seen_at = now() where id = r.id; end if;
    a := row(r.member_id, null, 'pwa', r.id, array['read','propose','post'])::bnx.actor;
  elsif cred->>'kind' = 'bearer' then
    select c.id cid, c.member_id, c.scopes, c.revoked_at crev, t.expires_at, t.revoked_at trev, m.state, t.resource into r   -- 9017: resource
      from bnx.ai_connection_token t join bnx.ai_connection c on c.id = t.connection_id
      join bnx.member m on m.id = c.member_id where t.token_sha256 = h and t.kind = 'access';
    if not found or r.trev is not null or r.crev is not null or now() > r.expires_at or r.state <> 'active' then
      perform bnx.fail('UNAUTHENTICATED', 'P0401');
    end if;
    -- 9017 (B7): a token issued for a resource is accepted only by the Gateway of that resource
    if cred ? 'audience' and r.resource is not null and r.resource is distinct from cred->>'audience' then
      perform bnx.fail('UNAUTHENTICATED', 'P0401');
    end if;
    a := row(r.member_id, r.cid, 'mcp', null, r.scopes)::bnx.actor;
  else
    perform bnx.fail('UNAUTHENTICATED', 'P0401');
  end if;
  perform set_config('bnx.actor_member', a.member_id::text, true);
  foreach k in array array['host_profile','tool_name','tool_version','trace_id'] loop
    val := cred->'envelope'->>k;
    if val is not null and (length(val) > 100 or val !~ '^[ -~]+$') then          -- 9011 G0R
      perform bnx.fail('VALIDATION_FAILED', 'P0422', 'envelope.' || k);
    end if;
    perform set_config('bnx.' || k, coalesce(val, ''), true);
  end loop;
  return a;
end $$;

-- ---------- catalog ----------
create function bnx.catalog_entries() returns table(core_function text, entry jsonb)
language sql stable security definer set search_path = pg_catalog, pg_temp as $$
  select n.nspname || '.' || p.proname, obj_description(p.oid, 'pg_proc')::jsonb
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname in (select nspname from bnx.schema_registry) and (p.proname like 'cmd\_%' or p.proname like 'q\_%')
     and has_function_privilege('bnx_app', p.oid, 'EXECUTE')
     and coalesce(obj_description(p.oid, 'pg_proc'), '') like '{%'
$$;

-- bnx-tools/1.0 for the Gateway: entries, their digest (sha256 over the canonical text, ordered by core function) and the
-- REST-callable functions without an entry (the Gateway answers 404 for those; AT-CAT-01 keeps the list empty)
create function bnx.wrk_catalog() returns jsonb
language plpgsql stable security definer set search_path = pg_catalog, pg_temp as $$
declare e jsonb; d text;
begin
  if session_user <> 'bnx_worker' then perform bnx.fail('FORBIDDEN', 'P0403'); end if;
  select coalesce(jsonb_agg(c.entry order by c.core_function collate "C"), '[]'),
         encode(sha256(convert_to(coalesce(string_agg(c.entry::text, E'\n' order by c.core_function collate "C"), ''), 'UTF8')), 'hex')
    into e, d from bnx.catalog_entries() c;
  return jsonb_build_object('format', 'bnx-tools/1.0', 'catalog_sha256', d, 'entries', e,
    'uncatalogued', coalesce((select jsonb_agg(n.nspname || '.' || p.proname order by p.proname) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
       where n.nspname in (select nspname from bnx.schema_registry) and (p.proname like 'cmd\_%' or p.proname like 'q\_%')
         and has_function_privilege('bnx_app', p.oid, 'EXECUTE') and coalesce(obj_description(p.oid, 'pg_proc'), '') not like '{%'), '[]'));
end $$;

-- ---------- binding facts (B1, B2, B3, B8; Amendment 03 §5.2, AE §6) ----------
create function bnx.wrk_binding_facts() returns jsonb
language plpgsql stable security definer set search_path = pg_catalog, pg_temp as $$
declare act bnx.config_version_anchor;
begin
  if session_user <> 'bnx_worker' then perform bnx.fail('FORBIDDEN', 'P0403'); end if;
  select * into act from bnx.config_version_anchor where state = 'ACTIVE';
  return jsonb_build_object(
    'identity', (select jsonb_build_object('project_id', project_id, 'instance_uid', instance_uid) from bnx.instance_identity),
    'active', case when act.config_version is null then null else jsonb_build_object('config_version', act.config_version,
                'config_sha256', act.config_sha256,
                'flags', coalesce((select jsonb_object_agg(flag_key, value) from bnx.instance_module_flag where config_version = act.config_version), '{}')) end,
    'deployable_sha256', coalesce((select jsonb_agg(config_sha256 order by config_version) from bnx.config_version_anchor
                                    where state in ('ACTIVE','PENDING_DEPLOY') and config_sha256 is not null), '[]'),
    'schema_head', jsonb_build_object(
       'core', (select max(version) from bnx.schema_migrations where version < '9000'),
       'extension', (select max(version) from bnx.schema_migrations where version >= '9000')),
    'catalog_sha256', (select encode(sha256(convert_to(coalesce(string_agg(c.entry::text, E'\n' order by c.core_function collate "C"), ''), 'UTF8')), 'hex')
                         from bnx.catalog_entries() c));
end $$;

-- ---------- work items of an unknown kind (UA §9.1; S4B-F13; AT-Q-02) ----------
-- The item stays leased until a back-off deadline (5 min x 2^(attempts-1), at most 3 h = one backstop period: a deferred
-- item never wakes Neon, so a longer cap would only delay recovery); wrk_claim re-claims it after
-- that (at the next backstop rescan at the latest), so a Worker release that understands the kind processes it. After 3
-- attempts the Owner is alerted once per kind and day. Never done, never dead.
create function bnx.wrk_defer_item(p_id bigint) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare w bnx.work_item; until_ timestamptz; alerted boolean := false;
begin
  if session_user <> 'bnx_worker' then perform bnx.fail('FORBIDDEN', 'P0403'); end if;
  select * into w from bnx.work_item where id = p_id for update;
  if not found then return jsonb_build_object('item_id', p_id, 'status', 'not_found'); end if;
  if w.state <> 'leased' then return jsonb_build_object('item_id', p_id, 'status', w.state); end if;
  until_ := now() + least(interval '5 minutes' * power(2, least(greatest(w.attempts - 1, 0), 10))::int, interval '3 hours');
  update bnx.work_item set lease_until = until_ where id = p_id;
  if w.attempts >= 3 then
    alerted := bnx.notify('EXCEPTION', 'WORK_KIND_UNKNOWN:' || left(w.kind, 60) || ':' || current_date, true,
                          jsonb_build_object('kind', 'WORK_KIND_UNKNOWN', 'record_key', left(w.kind, 60), 'count', w.attempts)) is not null;
  end if;
  return jsonb_build_object('item_id', p_id, 'status', 'deferred', 'attempts', w.attempts, 'retry_after', until_, 'alerted', alerted);
end $$;

-- ---------- presigned upload target (UA §8.1; AT-EV-01; O-7) ----------
-- Only the member who registered the file, only while it is upload_pending, never on an AI connection (as
-- cmd_register_evidence). An unknown or foreign file is NOT_AVAILABLE (INV-41: no oracle).
create function bnx.q_evidence_upload_target(cred jsonb, q jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); f record;
begin
  perform bnx.require(a, 1);
  if a.channel = 'mcp' then perform bnx.fail('FORBIDDEN_CHANNEL', 'P0403'); end if;
  if coalesce(q->>'evidence_file_id', '') !~ '^[0-9a-fA-F-]{36}$' then perform bnx.fail('VALIDATION_FAILED', 'P0422', 'evidence_file_id'); end if;
  select ef.id, ef.size_declared, ef.sha256_declared, ef.mime, eo.r2_key into f
    from bnx.evidence_file ef join bnx.evidence_object eo on eo.id = ef.evidence_object_id
   where ef.id = (q->>'evidence_file_id')::uuid and ef.acquired_by = a.member_id and ef.storage_state = 'upload_pending' and eo.r2_key is not null;
  if not found then perform bnx.fail('NOT_AVAILABLE', 'P0404'); end if;
  return jsonb_build_object('evidence_file_id', f.id, 'r2_key', f.r2_key, 'size_bytes', f.size_declared,
                            'sha256_declared', encode(f.sha256_declared, 'hex'), 'mime', f.mime);
end $$;

select bnx.apply_grants();

